std::vector<Monstey_Snapshot>Monstey_ReferenceSnapshots;std::size_t Monstey_Compared=0;U Monstey_DiffChecks=0,Monstey_DiffBytes=0;std::size_t Monstey_FirstBad=0;std::unique_ptr<Monstey_Snapshot>Monstey_BadReference,Monstey_BadActual;
void Monstey_DiffCheck(bool ok,const char*label,const Monstey_Snapshot&r,const Monstey_Snapshot&a){++Monstey_DiffChecks;if(!ok&&Monstey_DiffMismatch.empty()){Monstey_FirstBad=Monstey_Compared-1;Monstey_DiffMismatch=label;Monstey_BadReference=std::make_unique<Monstey_Snapshot>(r);Monstey_BadActual=std::make_unique<Monstey_Snapshot>(a);}}
Monstey_Fixture::~Monstey_Fixture(){try{Monstey_Snapshot now{base,bytes,events,cas,exchanges,outcomes};if(!actual){Monstey_ReferenceSnapshots.push_back(std::move(now));return;}const auto at=Monstey_Compared++;if(at>=Monstey_ReferenceSnapshots.size()){Monstey_DiffMismatch="extra actual case";return;}const auto&ref=Monstey_ReferenceSnapshots[at];Monstey_DiffBytes+=static_cast<U>(bytes.size());Monstey_DiffCheck(ref.base==now.base&&ref.bytes==now.bytes,"complete owned image mismatch",ref,now);Monstey_DiffCheck(ref.outcomes==now.outcomes,"raw/result/fault outcome mismatch",ref,now);Monstey_DiffCheck(ref.events==now.events,"typed import/frame/argument event mismatch",ref,now);Monstey_DiffCheck(ref.cas==now.cas,"nested actual CAS event mismatch",ref,now);bool equal=ref.exchange.size()==now.exchange.size();if(equal)for(std::size_t k=0;k<ref.exchange.size();++k){const auto&x=ref.exchange[k];const auto&y=now.exchange[k];equal=equal&&x.pc==y.pc&&x.address==y.address&&x.value==y.value;}Monstey_DiffCheck(equal,"exchange event mismatch",ref,now);}catch(...){if(Monstey_DiffMismatch.empty())Monstey_DiffMismatch="snapshot observer allocation error";}}
B::Monstey_Image Monstey_View(P::Monstey_GadbBinderMemory m){return {m.base,m.bytes,nullptr};}
P::Monstey_GadbBinderMemory Monstey_ProductMemory(Monstey_Fixture&f){return {f.base,std::span<std::uint8_t>(f.bytes)};}
